C++ exam: Given a graph and a source vertex, find the shortest path from the source to every other vertex using Dijkstra’s algorithm

###Response to evaluate:
Given a graph G and a source vertex s, Dijkstra’s algorithm can be used to find the shortest paths from s to every other vertex in the graph. The algorithm starts with s as the current node, with the distance from s to itself set to 0. Then, for each edge (u,v) in the graph, the algorithm checks if the distance from s to u is less than the distance from s to v. If so, then the distance from s to u is updated to be the distance from s to v plus the length of the edge (u,v). Next, the algorithm sets u as the new current node and repeats the process until the distance from s to every other vertex has been calculated. This will result in a path from s to every other vertex, which is the shortest path from s to each of those vertices.

###Reference Answer (Score 5):
To solve this problem using Dijkstra's algorithm in C++, follow the steps below:

1. Include the necessary headers
2. Define a function to find the Minimum Distances
3. Define the Dijkstra function
4. Create the main function to implement the algorithm

Here's a sample implementation:

```cpp
#include <iostream>
#include <climits>
#include <vector>
#include <queue>

using namespace std;

// Function to find the vertex with the minimum distance value
int minDistance(vector<int>& dist, vector<bool>& visited) {
    int min = INT_MAX, min_index;
    for (int v = 0; v < dist.size(); v++) {
        if (!visited[v] && dist[v] <= min) {
            min = dist[v], min_index = v;
        }
    }
    return min_index;
}

// Dijkstra function to implement the shortest path algorithm
void dijkstra(vector<vector<int>>& graph, int src) {
    int V = graph.size();
    vector<int> dist(V, INT_MAX); // Initialize distances
    vector<bool> visited(V, false); // Nodes status
    dist[src] = 0; // Distance of source vertex from itself is always 0

    for (int count = 0; count < V - 1; count++) {
        int u = minDistance(dist, visited);
        visited[u] = true;

        for (int v = 0; v < V; v++) {
            if (!visited[v] && graph[u][v] && dist[u] != INT_MAX && dist[u] + graph[u][v] < dist[v]) {
                dist[v] = dist[u] + graph[u][v];
            }
        }
    }

    // Print the shortest path distances from the source
    cout << "Shortest path distances from source vertex " << src << ":
";
    for (int i = 0; i < V; i++) {
        cout << "Vertex " << i << ": " << dist[i] << endl;
    }
}

int main() {
    vector<vector<int>> graph = {
        {0, 10, 20, 0, 0, 0},
        {10, 0, 0, 50, 10, 0},
        {20, 0, 0, 20, 33, 0},
        {0, 50, 20, 0, 20, 2},
        {0, 10, 33, 20, 0, 1},
        {0, 0, 0, 2, 1, 0}
    };

    int source_vertex = 0; // Define your source vertex
    dijkstra(graph, source_vertex); // Execute the Dijkstra function

    return 0;
}
```

This code will output the shortest path distances from the source vertex (in this case, 0) to all other vertices in the graph. 

